badExample:
interface User {
    name: string;
}
const u: User = { name: "Alex", age: 25 }; // Error TS2322: 'age' does not exist in type 'User'

fixedExample:
interface User {
    name: string;
    age?: number;
}
const u: User = { name: "Alex", age: 25 };

badExample:
function parse(raw: any) {
    return raw.profile.email.toLowerCase(); // Runtime crash if profile is undefined!
}

fixedExample:
interface ProfileData {
    profile?: { email?: string };
}
function parse(raw: ProfileData) {
    return raw.profile?.email?.toLowerCase() ?? "no-email";
}

badExample:
type Action = { type: 'success'; data: string } | { type: 'error'; error: string };
function handle(action: Action) {
    console.log(action.data); // Error TS2339: Property 'data' does not exist on type 'Action'
}

fixedExample:
type Action = { type: 'success'; data: string } | { type: 'error'; error: string };
function handle(action: Action) {
    if (action.type === 'success') {
        console.log(action.data);
    }
}

badExample:
function greet(name: string) { return `Hello ${name}`; }
const user: { name?: string } = {};
greet(user?.name); // Error TS2345: string | undefined not assignable to string

fixedExample:
function greet(name: string) { return `Hello ${name}`; }
const user: { name?: string } = {};
greet(user?.name ?? "Anonymous");

badExample:
function append(nums: readonly number[], val: number) {
    nums.push(val); // Error TS2339: Property 'push' does not exist on 'readonly number[]'
}

fixedExample:
function append(nums: readonly number[], val: number): number[] {
    return [...nums, val];
}

badExample:
interface ApiResponse { data: { id: string } }
const res = (JSON.parse(str) as unknown) as ApiResponse;
console.log(res.data.id); // Crash if str did not contain { data: { id } }!

fixedExample:
interface ApiResponse { data: { id: string } }
function isApiResponse(obj: any): obj is ApiResponse {
    return obj && typeof obj === 'object' && obj.data && typeof obj.data.id === 'string';
}
const parsed = JSON.parse(str);
if (isApiResponse(parsed)) {
    console.log(parsed.data.id);
}

export const Status = {
    Active: 'ACTIVE',
    Inactive: 'INACTIVE',
} as const;
export type Status = typeof Status[keyof typeof Status];
console.log(Object.keys(Status)); // ['Active', 'Inactive']

badExample:
function getId<T>(item: T) {
    return item.id; // Error TS2339: Property 'id' does not exist on type 'T'
}

fixedExample:
interface HasId {
    id: string;
}
function getId<T extends HasId>(item: T): string {
    return item.id;
}

badExample:
interface Config { port: number; host: string }
const cfg: Config = { port: 8080, host: 'localhost' };
Object.keys(cfg).forEach(k => {
    const v = cfg[k]; // Error TS7053: No index signature with parameter of type 'string'
});

fixedExample:
interface Config { port: number; host: string }
const cfg: Config = { port: 8080, host: 'localhost' };
(Object.keys(cfg) as (keyof Config)[]).forEach(k => {
    const v = cfg[k]; // Typed accurately as number | string
});
